INSERT INTO knowledge_points ("title", "content", "chapterNumber", "sortOrder", "importance", "tags") VALUES
('会计概念', '会计是以货币为主要计量单位，运用专门的方法，核算和监督一个单位经济活动的一种经济管理活动。', '1.1', 1, 'important', '["基础概念", "重点"]'),
('会计职能', '会计具有核算职能和监督职能，核算职能是基本职能，监督职能是重要职能。', '1.2', 2, 'important', '["基础概念", "重点"]'),
('会计基本假设', '会计主体、持续经营、会计分期、货币计量是会计核算的基本前提。', '1.3', 3, 'important', '["基础概念", "重点"]'),
('会计信息质量要求', '相关性、可靠性、可理解性、可比性、实质重于形式、重要性、谨慎性、及时性。', '1.4', 4, 'important', '["基础概念", "重点"]'),
('会计政策', '企业在会计确认、计量和报告中所采用的原则、基础和会计处理方法。', '2.1', 5, 'important', '["会计政策", "重点"]'),
('会计估计', '企业对其结果不确定的交易或事项以最近可利用的信息为基础所作的判断。', '2.2', 6, 'important', '["会计估计", "重点"]'),
('前期差错更正', '企业发现前期财务报表存在错误时的处理方法。', '2.3', 7, 'important', '["差错更正", "重点"]'),
('存货的确认', '存货是指企业在日常活动中持有以备出售的产成品或商品、处在生产过程中的在产品、在生产过程或提供劳务过程中耗用的材料和物料等。', '3.1', 8, 'important', '["存货", "重点"]'),
('存货的初始计量', '存货应当按照成本进行初始计量。存货成本包括采购成本、加工成本和其他成本。', '3.2', 9, 'important', '["存货", "重点"]'),
('发出存货的计量', '企业应当采用先进先出法、移动加权平均法、月末一次加权平均法或者个别计价法确定发出存货的实际成本。', '3.3', 10, 'important', '["存货", "重点"]');
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags") VALUES
('下列各项中，属于会计信息质量要求的是（）', 'single', '["A. 相关性", "B. 重要性", "C. 谨慎性", "D. 以上都是"]', 'D', '会计信息质量要求包括相关性、可靠性、可理解性、可比性、实质重于形式、重要性、谨慎性和及时性。', 4, 'easy', '["基础题", "概念题"]'),
('企业购入材料一批，价款10000元，增值税1300元，运杂费500元，该批材料的入账价值为（）元', 'single', '["A. 10000", "B. 10500", "C. 11300", "D. 11800"]', 'B', '材料的入账价值=买价+运杂费=10000+500=10500元，增值税可以抵扣，不计入材料成本。', 9, 'medium', '["计算题", "存货"]'),
('会计的基本职能包括（）', 'multiple', '["A. 核算职能", "B. 监督职能", "C. 预测职能", "D. 决策职能"]', 'AB', '会计的基本职能是核算职能和监督职能，其中核算职能是基本职能。', 2, 'easy', '["基础题", "概念题"]'),
('会计主体假设要求企业应当对其本身发生的交易或事项进行会计确认、计量和报告。（）', 'judge', '[]', '正确', '会计主体假设明确了会计核算的空间范围，要求企业只对自身的交易或事项进行会计处理。', 3, 'easy', '["基础题", "判断题"]');
INSERT INTO knowledge_points ("title", "content", "chapterNumber", "sortOrder", "importance", "tags") VALUES
('固定资产', '固定资产是指同时具有下列特征的有形资产：为生产商品、提供劳务、出租或经营管理而持有的，使用寿命超过一个会计年度。固定资产折旧、后续支出与减值处理是核心考点。', '4.1', 11, 'important', '["固定资产", "重点"]'),
('无形资产', '无形资产是指企业拥有或者控制的没有实物形态的可辨认非货币性资产。使用寿命的确定与摊销是核心考点。', '4.2', 12, 'important', '["无形资产", "重点"]'),
('投资性房地产', '投资性房地产是指为赚取租金或资本增值，或两者兼有而持有的房地产。公允价值模式与成本模式转换是核心考点。', '4.3', 13, 'important', '["投资性房地产", "重点"]'),
('金融资产', '金融资产包括交易性金融资产、持有至到期投资、可供出售金融资产、应收款项等。初始计量与后续计量的差异是核心考点。', '4.4', 14, 'important', '["金融资产", "重点"]'),
('长期股权投资', '长期股权投资包括对子公司、合营企业、联营企业的投资。成本法与权益法的适用及核算差异是核心考点。', '4.5', 15, 'important', '["长期股权投资", "重点"]'),
('非货币性资产交换', '非货币性资产交换是指交易双方主要以存货、固定资产、无形资产和长期股权投资等非货币性资产进行的交换。商业实质判断与计量基础是核心考点。', '4.6', 16, 'important', '["非货币性资产交换", "重点"]'),
('债务重组', '债务重组是指在债务人发生财务困难的情况下，债权人按照其与债务人达成的协议或法院的裁定作出让步的事项。', '5.1', 17, 'important', '["债务重组", "重点"]'),
('或有事项', '或有事项是指过去的交易或者事项形成的，其结果须由某些未来事项的发生或不发生才能决定的不确定事项。预计负债的确认与计量是核心考点。', '5.2', 18, 'important', '["或有事项", "重点"]'),
('收入确认', '销售商品收入的确认须同时满足五个条件。商业折扣、以旧换新、附退货条款等特殊情形的处理是核心考点。', '5.3', 19, 'important', '["收入", "重点"]'),
('政府与民间非营利组织会计', '政府会计与企业会计存在明显差异，事业单位净资产（事业基金）的变动、民间非营利组织净资产分类是核心考点。', '5.4', 20, 'basic', '["政府会计"]'),
('所得税', '所得税会计采用资产负债表债务法，核心是暂时性差异的识别与递延所得税资产、递延所得税负债的确认。', '6.1', 21, 'important', '["所得税", "难点"]'),
('外币折算', '外币交易采用交易发生日的即期汇率折算；外币货币性项目在资产负债表日按即期汇率调整并确认汇兑差额。', '6.2', 22, 'important', '["外币折算"]'),
('会计政策变更', '会计政策变更的累积影响数应调整比较财务报表最早期间的期初留存收益，其他相关项目的金额也应一并调整。', '6.3', 23, 'important', '["会计政策变更"]'),
('资产负债表日后事项', '资产负债表日后事项分为调整事项与非调整事项。判断标准是是否在资产负债表日已经存在或发生。', '6.4', 24, 'important', '["日后事项"]'),
('合并财务报表', '合并财务报表的编制以个别财务报表为基础，抵销内部交易与内部债权债务是核心考点。', '6.5', 25, 'important', '["合并报表", "难点"]'),
('股份支付', '股份支付分为以权益结算和以现金结算两类。等待期内的会计处理、行权时的资本公积结转是核心考点。', '6.6', 26, 'important', '["股份支付", "难点"]');
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('下列各项中，属于非货币性资产的是（　　）。', 'single', '["A. 外埠存款", "B. 持有的银行承兑汇票", "C. 拟长期持有的股票投资", "D. 准备持有至到期的债券投资"]', 'C', '非货币性资产是指货币性资产以外的资产。外埠存款、持有的银行承兑汇票、准备持有至到期的债券投资均属于货币性资产；拟长期持有的股票投资属于非货币性资产。', (SELECT id FROM knowledge_points WHERE title='非货币性资产交换'), 'easy', '["真题", "概念题"]', '官方真题-2012', 2012),
('2011年7月1日，甲公司将一项按照成本模式进行后续计量的投资性房地产转换为固定资产。该资产转换前的账面原价为4000万元，已计提折旧200万元，已计提减值准备100万元，转换日的公允价值为3850万元。假定不考虑其他因素，转换日甲公司应借记"固定资产"科目的金额为（　　）万元。', 'single', '["A. 3700", "B. 3800", "C. 3850", "D. 4000"]', 'A', '成本模式计量的投资性房地产转换为固定资产，应按账面价值结转：4000－200－100＝3700（万元），不确认转换损益。', (SELECT id FROM knowledge_points WHERE title='投资性房地产'), 'medium', '["真题", "计算题"]', '官方真题-2012', 2012),
('房地产开发企业已用于在建商品房的土地使用权，在资产负债表中应列示的项目为（　　）。', 'single', '["A. 存货", "B. 固定资产", "C. 无形资产", "D. 投资性房地产"]', 'A', '房地产开发企业已用于在建商品房的土地使用权，属于为建造商品房而购入的土地，应作为存货核算。', (SELECT id FROM knowledge_points WHERE title='存货的确认'), 'easy', '["真题", "概念题"]', '官方真题-2012', 2012),
('2011年11月15日，甲公司与乙公司签订了一份不可撤销的商品购销合同，约定甲公司于2012年1月15日按每件2万元向乙公司销售W产品100件。2011年12月31日，甲公司库存该产品100件，每件实际成本和市场价格分别为1.8万元和1.86万元。甲公司预计向乙公司销售该批产品将发生相关税费10万元。假定不考虑其他因素，甲公司该批产品在2011年12月31日资产负债表中应列示的金额为（　　）万元。', 'single', '["A. 176", "B. 180", "C. 186", "D. 190"]', 'B', '该批产品售价固定为2万元/件，可变现净值＝100×2－10＝190（万元），成本＝100×1.8＝180（万元），成本低于可变现净值，按成本180万元列示。', (SELECT id FROM knowledge_points WHERE title='存货的确认'), 'medium', '["真题", "计算题"]', '官方真题-2012', 2012),
('甲公司以M设备换入乙公司N设备，另向乙公司支付补价5万元，该项交换具有商业实质。交换日，M设备账面原价为66万元，已计提折旧9万元，已计提减值准备8万元，公允价值无法合理确定；N设备公允价值为72万元。假定不考虑其他因素，该项交换对甲公司当期损益的影响金额为（　　）万元。', 'single', '["A. 0", "B. 6", "C. 11", "D. 18"]', 'D', '换入资产N设备公允价值为72万元，换出M设备账面价值＝66－9－8＝49（万元），另支付补价5万元，差额72－49－5＝18（万元）计入当期损益。', (SELECT id FROM knowledge_points WHERE title='非货币性资产交换'), 'medium', '["真题", "计算题"]', '官方真题-2012', 2012),
('2011年5月20日，甲公司以银行存款200万元（其中包含乙公司已宣告但尚未发放的现金股利5万元）从二级市场购入乙公司100万股普通股股票，另支付相关交易费用1万元，甲公司将其划分为交易性金融资产。2011年12月31日，该股票投资的公允价值为210万元。假定不考虑其他因素，该股票投资对甲公司2011年度营业利润的影响金额为（　　）万元。', 'single', '["A. 14", "B. 15", "C. 19", "D. 20"]', 'A', '交易性金融资产入账价值＝200－5＝195（万元），公允价值变动收益＝210－195＝15（万元），交易费用1万元计入投资收益，影响营业利润＝15－1＝14（万元）。', (SELECT id FROM knowledge_points WHERE title='金融资产'), 'medium', '["真题", "计算题"]', '官方真题-2012', 2012),
('2012年1月1日，甲公司从二级市场购入丙公司面值为200万元的债券，支付的总价款为195万元（其中包括已到付息期但尚未领取的利息4万元），另支付相关交易费用1万元，甲公司将其划分为可供出售金融资产。该资产入账时应记入"可供出售金融资产——利息调整"科目的金额为（　　）。', 'single', '["A. 4（借方）", "B. 4（贷方）", "C. 8（借方）", "D. 8（贷方）"]', 'D', '可供出售金融资产初始入账价值＝195－4＋1＝192（万元），面值200万元，差额8万元记入"利息调整"贷方。', (SELECT id FROM knowledge_points WHERE title='金融资产'), 'hard', '["真题", "计算题"]', '官方真题-2012', 2012),
('2011年1月1日，甲公司以银行存款1100万元购入乙公司当日发行的面值为1000万元的5年期不可赎回债券，将其划分为持有至到期投资。该债券票面年利率为10%，每年付息一次，实际年利率为7.53%。2011年12月31日，该债券的公允价值上涨至1150万元。假定不考虑其他因素，2011年12月31日甲公司该债券投资的账面价值为（　　）万元。', 'single', '["A. 1082.83", "B. 1150", "C. 1182.83", "D. 1200"]', 'A', '持有至到期投资按摊余成本计量。账面价值＝1100×（1＋7.53%）－1000×10%＝1182.83－100＝1082.83（万元），公允价值变动不影响其账面价值。', (SELECT id FROM knowledge_points WHERE title='金融资产'), 'hard', '["真题", "计算题"]', '官方真题-2012', 2012),
('2010年1月1日，甲公司向50名高管人员每人授予2万份股票期权，这些人员从被授予股票期权之日起连续服务满2年，即可按每股6元的价格购买甲公司2万股普通股股票（每股面值1元）。该期权在授予日的公允价值为每份12元。2011年10月20日，甲公司从二级市场以每股15元的价格回购本公司普通股股票100万股，拟用于高管人员股权激励。在等待期内，甲公司没有高管人员离职。2011年12月31日，高管人员全部行权，当日甲公司普通股市场价格为每股16元。2011年12月31日，甲公司因高管人员行权应确认的股本溢价为（　　）万元。', 'single', '["A. 200", "B. 300", "C. 500", "D. 1700"]', 'B', '行权时：银行存款＝50×2×6＝600（万元），结转等待期确认的资本公积——其他资本公积＝50×2×12＝1200（万元），冲减库存股100×15＝1500（万元），股本＝100（万元），股本溢价＝600＋1200－1500－100＝300（万元）。', (SELECT id FROM knowledge_points WHERE title='股份支付'), 'hard', '["真题", "计算题"]', '官方真题-2012', 2012),
('甲公司因乙公司发生严重财务困难，预计难以全额收回乙公司所欠货款120万元。经协商，乙公司以银行存款90万元结清了全部债务。甲公司对该项应收账款已计提坏账准备12万元。假定不考虑其他因素，债务重组日甲公司应确认的损失为（　　）万元。', 'single', '["A. 0", "B. 12", "C. 18", "D. 30"]', 'C', '债务重组损失＝应收账款账面价值120－12－收到银行存款90＝18（万元）。', (SELECT id FROM knowledge_points WHERE title='债务重组'), 'medium', '["真题", "计算题"]', '官方真题-2012', 2012),
('因债务重组已确认为预计负债的或有应付金额，在随后会计期间最终没有发生的，企业应冲销已确认的预计负债，同时确认为（　　）。', 'single', '["A. 资本公积", "B. 财务费用", "C. 营业外支出", "D. 营业外收入"]', 'D', '或有应付金额在随后会计期间没有发生的，企业应当冲销已确认的预计负债，同时确认营业外收入。', (SELECT id FROM knowledge_points WHERE title='债务重组'), 'easy', '["真题", "概念题"]', '官方真题-2012', 2012),
('甲公司因违约被起诉，至2011年12月31日，人民法院尚未作出判决。经向公司法律顾问咨询，人民法院的最终判决很可能对本公司不利，预计赔偿金额为20万元至50万元，而且该区间内每个金额发生的可能性大致相同。甲公司2011年12月31日由此应确认预计负债的金额为（　　）万元。', 'single', '["A. 20", "B. 30", "C. 35", "D. 50"]', 'C', '连续区间且各种结果发生的可能性相同，应按中间值确认预计负债：（20＋50）÷2＝35（万元）。', (SELECT id FROM knowledge_points WHERE title='或有事项'), 'easy', '["真题", "计算题"]', '官方真题-2012', 2012),
('2011年12月31日，甲公司因交易性金融资产和可供出售金融资产的公允价值变动，分别确认了10万元的递延所得税资产和20万元的递延所得税负债。甲公司当期应交所得税的金额为150万元。假定不考虑其他因素，该公司2011年度利润表"所得税费用"项目应列示的金额为（　　）万元。', 'single', '["A. 120", "B. 140", "C. 160", "D. 180"]', 'C', '所得税费用＝当期所得税＋递延所得税费用＝150＋（－10＋20）＝160（万元）。', (SELECT id FROM knowledge_points WHERE title='所得税'), 'hard', '["真题", "计算题"]', '官方真题-2012', 2012),
('在资产负债表日至财务报告批准报出日之间发生的下列事项中，属于资产负债表日后非调整事项的是（　　）。', 'single', '["A. 以资本公积转增股本", "B. 发现了财务报表舞弊", "C. 发现原预计的资产减值损失严重不足", "D. 实际支付的诉讼赔偿额与原预计金额有较大差异"]', 'A', '以资本公积转增股本是资产负债表日后发生的事项，不影响资产负债表日存在状况，属于非调整事项；其余各项均属于调整事项。', (SELECT id FROM knowledge_points WHERE title='资产负债表日后事项'), 'medium', '["真题", "概念题"]', '官方真题-2012', 2012),
('下列各项中，应计入其他资本公积但不属于其他综合收益的是（　　）。', 'single', '["A. 溢价发行股票形成的资本公积", "B. 因享有联营企业其他综合收益形成的资本公积", "C. 可供出售金融资产公允价值变动形成的资本公积", "D. 以权益结算的股份支付在等待期内形成的资本公积"]', 'D', '以权益结算的股份支付在等待期内确认的资本公积属于其他资本公积，但不属于其他综合收益。', (SELECT id FROM knowledge_points WHERE title='股份支付'), 'hard', '["真题", "概念题"]', '官方真题-2012', 2012);
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('下列各项中，企业在判断存货成本与可变现净值孰低时，可作为存货成本确凿证据的有（　　）。', 'multiple', '["A. 外来原始凭证", "B. 生产成本资料", "C. 生产预算资料", "D. 生产成本账簿记录"]', 'ABD', '生产预算资料属于预算数据，不是存货成本的确凿证据；外来原始凭证、生产成本资料和生产成本账簿记录均属于确凿证据。', (SELECT id FROM knowledge_points WHERE title='存货的确认'), 'easy', '["真题", "概念题"]', '官方真题-2012', 2012),
('下列关于固定资产会计处理的表述中，正确的有（　　）。', 'multiple', '["A. 未投入使用的固定资产不应计提折旧", "B. 特定固定资产弃置费用的现值应计入该资产的成本", "C. 融资租入管理用固定资产发生的日常修理费应计入当期损益", "D. 预期通过使用或处置不能产生经济利益的固定资产应予终止确认"]', 'BCD', '未投入使用的固定资产仍应计提折旧，A错误；弃置费用现值计入固定资产成本，B正确；固定资产日常修理费计入当期损益，C正确；预期不能产生经济利益的固定资产应终止确认，D正确。', (SELECT id FROM knowledge_points WHERE title='固定资产'), 'medium', '["真题", "概念题"]', '官方真题-2012', 2012),
('企业在估计无形资产使用寿命时应考虑的因素有（　　）。', 'multiple', '["A. 无形资产相关技术的未来发展情况", "B. 使用无形资产生产的产品寿命周期", "C. 使用无形资产生产的产品市场需求情况", "D. 现在或潜在的竞争者预期将采取的研发战略"]', 'ABCD', '估计无形资产使用寿命时应综合考虑法律、合同规定以及技术、市场、竞争等多种因素，四项均属于应考虑的因素。', (SELECT id FROM knowledge_points WHERE title='无形资产'), 'medium', '["真题", "概念题"]', '官方真题-2012', 2012),
('甲公司将持有的乙公司20%有表决权的股份作为长期股权投资，并采用权益法核算。2011年12月25日，甲公司以银行存款1000万元从乙公司购入一批产品作为存货核算，至12月31日尚未出售。乙公司生产该批产品的实际成本为800万元，2011年度利润表列示的净利润为3000万元。假定不考虑其他因素，下列关于甲公司会计处理的表述中，正确的有（　　）。', 'multiple', '["A. 合并财务报表中抵销存货40万元", "B. 个别财务报表中确认投资收益560万元", "C. 合并财务报表中抵销营业成本160万元", "D. 合并财务报表中抵销营业收入1000万元"]', 'AB', '内部交易未实现利润＝（1000－800）×20%＝40（万元），合并报表抵销存货40万元，A正确；个别报表投资收益＝（3000－200）×20%＝560（万元），B正确；合并报表应抵销营业收入1000万元、营业成本800万元，C、D错误。', (SELECT id FROM knowledge_points WHERE title='长期股权投资'), 'hard', '["真题", "计算题"]', '官方真题-2012', 2012),
('不具有商业实质、不涉及补价的非货币性资产交换中，影响换入资产入账价值的因素有（　　）。', 'multiple', '["A. 换出资产的账面余额", "B. 换出资产的公允价值", "C. 换入资产的公允价值", "D. 换出资产已计提的减值准备"]', 'AD', '不具有商业实质的非货币性资产交换，应以换出资产的账面价值为基础确定换入资产入账价值，账面余额与已计提的减值准备影响账面价值；公允价值不参与计量。', (SELECT id FROM knowledge_points WHERE title='非货币性资产交换'), 'medium', '["真题", "概念题"]', '官方真题-2012', 2012),
('下列关于股份支付的会计处理中，正确的有（　　）。', 'multiple', '["A. 以回购股份奖励本企业职工的，应作为以权益结算的股份支付进行处理", "B. 在等待期内的每个资产负债表日，将取得职工提供的服务计入成本费用", "C. 权益结算的股份支付应在可行权日后对已确认成本费用和所有者权益进行调整", "D. 为换取职工提供服务所发生的以权益结算的股份支付，应以所授予权益工具的公允价值计量"]', 'ABD', '权益结算的股份支付在可行权日后不再对已确认的成本费用和所有者权益进行调整，C错误；A、B、D表述均正确。', (SELECT id FROM knowledge_points WHERE title='股份支付'), 'medium', '["真题", "概念题"]', '官方真题-2012', 2012),
('债务人发生财务困难、债权人作出让步是债务重组的基本特征。下列各项中，属于债权人作出让步的有（　　）。', 'multiple', '["A. 债权人减免债务人部分债务本金", "B. 债权人免去债务人全部应付利息", "C. 债权人同意债务人以公允价值高于重组债务账面价值的股权清偿债务", "D. 债权人同意债务人以公允价值低于重组债务账面价值的非现金资产清偿债务"]', 'ABD', '债权人作出让步是指同意债务人以低于重组债务账面价值的金额偿还债务。以公允价值高于账面价值的股权清偿不属于让步，C错误。', (SELECT id FROM knowledge_points WHERE title='债务重组'), 'medium', '["真题", "概念题"]', '官方真题-2012', 2012),
('下列各项中，能够产生应纳税暂时性差异的有（　　）。', 'multiple', '["A. 账面价值大于其计税基础的资产", "B. 账面价值小于其计税基础的负债", "C. 超过税法扣除标准的业务宣传费", "D. 按税法规定可以结转以后年度的未弥补亏损"]', 'AB', '应纳税暂时性差异是未来应纳税的差异，产生于账面价值大于计税基础的资产和账面价值小于计税基础的负债；C、D产生可抵扣暂时性差异。', (SELECT id FROM knowledge_points WHERE title='所得税'), 'hard', '["真题", "概念题"]', '官方真题-2012', 2012),
('下列各项中，表明已售商品所有权上的主要风险和报酬尚未转移给购货方的有（　　）。', 'multiple', '["A. 销售商品的同时，约定日后将以融资租赁方式租回", "B. 销售商品的同时，约定日后将以高于原售价的固定价格回购", "C. 已售商品附有无条件退货条款，但不能合理估计退货的可能性", "D. 向购货方发出商品后，发现商品质量与合同不符，很可能遭受退货"]', 'ABCD', '融资租赁租回、固定价格回购、无条件退货且不能合理估计、质量不符很可能退货，均表明主要风险和报酬尚未转移，四项均正确。', (SELECT id FROM knowledge_points WHERE title='收入确认'), 'medium', '["真题", "概念题"]', '官方真题-2012', 2012),
('下列各项中，会引起事业单位年末资产负债表中事业基金总额发生变化的有（　　）。', 'multiple', '["A. 购入国库券", "B. 以银行存款购入固定资产", "C. 提取职工福利基金", "D. 将闲置固定资产对外投资"]', 'BCD', '购入国库券只是货币资金形态的变化，不影响事业基金总额；购入固定资产、提取职工福利基金、将固定资产对外投资均会引起事业基金总额发生变化。', (SELECT id FROM knowledge_points WHERE title='政府与民间非营利组织会计'), 'hard', '["真题", "概念题"]', '官方真题-2012', 2012);
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('所有者权益体现的是所有者在企业中的剩余权益，其确认和计量主要依赖于资产、负债等其他会计要素的确认和计量。（　　）', 'judge', '[]', '正确', '所有者权益是资产减去负债后的剩余权益，其确认和计量依赖于资产、负债等会计要素的确认和计量。', (SELECT id FROM knowledge_points WHERE title='会计概念'), 'easy', '["真题", "判断题"]', '官方真题-2012', 2012),
('已采用公允价值模式计量的投资性房地产，不得从公允价值计量模式转换为成本计量模式。（　　）', 'judge', '[]', '正确', '已采用公允价值模式计量的投资性房地产，不得从公允价值模式转换为成本模式；成本模式可以转为公允价值模式。', (SELECT id FROM knowledge_points WHERE title='投资性房地产'), 'easy', '["真题", "判断题"]', '官方真题-2012', 2012),
('对于比较财务报表可比期间以前的会计政策变更的累积影响数，应调整比较财务报表最早期间的期初留存收益，财务报表其他相关项目的金额也应一并调整。（　　）', 'judge', '[]', '正确', '会计政策变更采用追溯调整法时，累积影响数应调整比较财务报表最早期间的期初留存收益，其他相关项目一并调整。', (SELECT id FROM knowledge_points WHERE title='会计政策变更'), 'medium', '["真题", "判断题"]', '官方真题-2012', 2012),
('企业销售商品涉及商业折扣的，应按扣除商业折扣前的金额确定商品销售收入金额。（　　）', 'judge', '[]', '错误', '企业销售商品涉及商业折扣的，应当按照扣除商业折扣后的金额确定销售商品收入金额。', (SELECT id FROM knowledge_points WHERE title='收入确认'), 'easy', '["真题", "判断题"]', '官方真题-2012', 2012),
('对认股权和债券分离交易的可转换公司债券，认股权持有人到期没有行权的，发行企业应在认股权到期时，将原计入资本公积的部分转入营业外收入。（　　）', 'judge', '[]', '错误', '认股权持有人到期没有行权的，发行企业应在认股权到期时，将原计入资本公积（其他资本公积）的部分转入资本公积（股本溢价），而非营业外收入。', (SELECT id FROM knowledge_points WHERE title='股份支付'), 'hard', '["真题", "判断题"]', '官方真题-2012', 2012),
('非同一控制下的企业合并中，因资产、负债的入账价值与其计税基础不同产生的递延所得税资产或递延所得税负债，其确认结果将影响购买日的所得税费用。（　　）', 'judge', '[]', '错误', '非同一控制下企业合并中产生的递延所得税资产或递延所得税负债，其确认结果应调整购买日确认的商誉或计入当期损益的合并差额，不影响购买日的所得税费用。', (SELECT id FROM knowledge_points WHERE title='所得税'), 'hard', '["真题", "判断题"]', '官方真题-2012', 2012),
('企业采用以旧换新方式销售商品时，应将所售商品按照销售商品收入确认条件确认收入，回收的商品作为购进商品处理。（　　）', 'judge', '[]', '正确', '以旧换新销售商品，销售商品按收入确认条件确认收入，回收的旧商品作为购进商品处理。', (SELECT id FROM knowledge_points WHERE title='收入确认'), 'easy', '["真题", "判断题"]', '官方真题-2012', 2012),
('企业对境外经营财务报表进行折算时，资产负债表各项目均采用资产负债表日的即期汇率折算，利润表各项目均采用交易发生日的即期汇率或与交易发生日即期汇率近似的汇率折算。（　　）', 'judge', '[]', '错误', '资产负债表中的资产和负债项目采用资产负债表日的即期汇率折算，但所有者权益项目除"未分配利润"项目外，采用发生时的即期汇率折算，并非所有项目均采用资产负债表日即期汇率。', (SELECT id FROM knowledge_points WHERE title='外币折算'), 'medium', '["真题", "判断题"]', '官方真题-2012', 2012),
('资产负债表日后事项如涉及现金收支项目，均不调整报告年度资产负债表的货币资金项目和现金流量表各项目数字。（　　）', 'judge', '[]', '正确', '资产负债表日后事项涉及现金收支的，均不调整报告年度资产负债表的货币资金项目和现金流量表正表各项目数字。', (SELECT id FROM knowledge_points WHERE title='资产负债表日后事项'), 'medium', '["真题", "判断题"]', '官方真题-2012', 2012),
('民间非营利组织的限定性净资产的限制即使已经解除，也不应当对净资产进行重新分类。（　　）', 'judge', '[]', '错误', '民间非营利组织限定性净资产的限制已经解除的，应当对净资产进行重新分类，将限定性净资产转为非限定性净资产。', (SELECT id FROM knowledge_points WHERE title='政府与民间非营利组织会计'), 'medium', '["真题", "判断题"]', '官方真题-2012', 2012);
INSERT INTO knowledge_points ("title", "content", "chapterNumber", "sortOrder", "importance", "tags") VALUES
('政府补助', '政府补助是指企业从政府无偿取得货币性资产或非货币性资产。与收益相关的政府补助用于补偿已发生成本费用的，直接计入当期损益或冲减相关成本费用。', '5.5', 27, 'important', '["政府补助", "重点"]'),
('租赁', '租赁是指在约定的期间内，出租人将资产使用权让与承租人以获取对价的合同。承租人对使用权资产、租赁负债的确认与后续计量是核心考点。', '6.7', 28, 'important', '["租赁", "重点"]'),
('职工薪酬', '职工薪酬包括短期薪酬、离职后福利、辞退福利和其他长期职工福利。设定受益计划的核算与重新计量是核心考点。', '6.8', 29, 'important', '["职工薪酬"]');
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('下列各项中，属于企业会计估计变更的是（　　）。', 'single', '["A. 将投资性房地产后续计量方法由成本模式变更为公允价值模式", "B. 因追加投资将长期股权投资的核算方法由权益法转为成本法", "C. 无形资产的预计使用年限由6年变更为4年", "D. 把发出存货的计价方法由先进先出法变更为移动加权平均法"]', 'C', '选项A，投资性房地产后续计量模式由成本模式变更为公允价值模式，属于会计政策变更；选项B，属于本期发生的交易或事项与以前相比具有本质差别而采用新的会计政策；选项D，属于会计政策变更。', (SELECT id FROM knowledge_points WHERE title='会计估计'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023);
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('下列各项中，应计入制造费用的有（　　）。', 'multiple', '["A. 生产部门管理人员的养老保障金", "B. 生产部门管理人员的补偿金", "C. 生产部门管理人员的住房公积金", "D. 生产部门管理人员居住的企业自有用房的折旧费"]', 'ABCD', '生产部门管理人员的工资及福利费用，属于产品的间接成本，计入制造费用。', (SELECT id FROM knowledge_points WHERE title='存货的确认'), 'easy', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('下列各事项中，应计入制造型企业投资性房地产的有（　　）。', 'multiple', '["A. 准备增值后转让的企业自有土地使用权", "B. 建设完成并以经营租赁方式出租的自有办公楼", "C. 租入后转租的仓库", "D. 以经营租赁方式出租的自有土地使用权"]', 'ABD', '投资性房地产主要包括已出租的土地使用权、持有并准备增值后转让的土地使用权和已出租的建筑物。选项C，租入后转租的仓库，企业不拥有所有权，不属于投资性房地产。', (SELECT id FROM knowledge_points WHERE title='投资性房地产'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('下列各项中，属于以公允价值计量第二层次输入值的有（　　）。', 'multiple', '["A. 非活跃市场的相同资产的市场价格计量其他权益工具投资", "B. 非活跃市场的相似资产的市场价格计量投资性房地产", "C. 活跃市场的相同资产的市场价格计量交易性金融资产", "D. 活跃市场的相似资产的市场价格计量其他债权投资"]', 'ABD', '第二层次输入值是除第一层次输入值外相关资产或负债直接或间接可观察的输入值，包括活跃市场中类似资产或负债的报价、非活跃市场中相同或类似资产或负债的报价、除报价以外的其他可观察输入值等。', (SELECT id FROM knowledge_points WHERE title='金融资产'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('企业某固定资产成本为1000万元，2021年计提折旧100万元，减值准备20万元，2022年计提折旧50万元。2022年12月31日，公允价值减处置费用后的净额为800万元，未来现金流量现值为810万元（税前），预计处置资产发生相关税费为4万元。2023年重新计提折旧，预计剩余使用年限为5年，净残值为0，采用年限平均法计提折旧。不考虑其他因素，下列说法正确的有（　　）。', 'multiple', '["A. 2022年12月31日，固定资产减值准备余额为44万元", "B. 2022年12月31日，可收回金额为810万元", "C. 2023年折旧金额为161.2万元", "D. 2022年12月31日计提减值损失20万元"]', 'BD', '2022年12月31日，固定资产计提减值准备前的账面价值＝1000－100－20－50＝830（万元），可收回金额为公允价值减去处置费用后的净额与未来现金流量现值中的较高者810万元，计提固定资产减值准备＝830－810＝20（万元）。2023年折旧金额＝810÷5＝162（万元）。', (SELECT id FROM knowledge_points WHERE title='固定资产'), 'hard', '["真题", "计算题"]', '考生回忆版-2023', 2023),
('甲公司为增值税一般纳税人，2×23年2月1日，甲公司委托乙公司加工一批M产品（属于应税消费品，非黄金饰品），2×23年3月15日，甲公司回收并直接销售，应计入M产品成本的有（　　）。', 'multiple', '["A. 向乙公司支付的不含税加工费6万元", "B. 发出用于委托加工的原材料30万元", "C. 向乙公司支付的代收代缴消费税4万元", "D. 向乙公司支付与加工费相关增值税0.38万元，取得增值税专用发票"]', 'ABC', '委托加工物资收回后直接销售的，受托方代收代缴的消费税计入委托加工物资成本；支付的与加工费相关的增值税取得专用发票可以抵扣，不计入成本，选项D错误。', (SELECT id FROM knowledge_points WHERE title='存货的初始计量'), 'medium', '["真题", "计算题"]', '考生回忆版-2023', 2023);
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('对于违反会计行为准则并承担刑事责任的人员，单位不得任用其从事会计工作。（　　）', 'judge', '[]', '正确', '因发生与会计职务有关的违法行为被依法追究刑事责任的人员，单位不得任用（聘用）其从事会计工作。', (SELECT id FROM knowledge_points WHERE title='会计概念'), 'easy', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('企业收到用于弥补以前年度自然灾害的政府补助资金，应调整本年期初留存收益。（　　）', 'judge', '[]', '错误', '与收益相关的政府补助如果用于补偿企业已发生的相关成本费用或损失，企业应当将其直接计入当期损益或冲减相关成本费用。', (SELECT id FROM knowledge_points WHERE title='政府补助'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('对于指定为以公允价值计量且其变动计入其他综合收益的非交易性权益工具投资，不计提减值准备。（　　）', 'judge', '[]', '正确', '指定为以公允价值计量且其变动计入其他综合收益的非交易性权益工具投资不需计提减值准备。', (SELECT id FROM knowledge_points WHERE title='金融资产'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('对于无法区分为会计政策变更还是会计估计变更的事项，都应按照会计政策变更处理。（　　）', 'judge', '[]', '错误', '企业难以对某项变更区分为会计政策变更或会计估计变更的，应当将其作为会计估计变更处理。', (SELECT id FROM knowledge_points WHERE title='会计估计'), 'easy', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('债务人无财务困难，与债权人商定延期支付本息的，债务人应按债务重组核算。（　　）', 'judge', '[]', '正确', '债务重组是指在不改变交易对手方的情况下，经债权人和债务人协定或法院裁定，就清偿债务的时间、金额或方式等重新达成协议的交易，不强调债务人发生财务困难，也不论债权人是否作出让步。', (SELECT id FROM knowledge_points WHERE title='债务重组'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('在建的试运行中产生的产品进行销售，其产品的销售收入和成本应计入当期损益。（　　）', 'judge', '[]', '正确', '企业将固定资产达到预定可使用状态前或研发过程中产出的产品或副产品对外销售的，应当对试运行销售相关的收入和成本分别进行会计处理，计入当期损益。', (SELECT id FROM knowledge_points WHERE title='固定资产'), 'easy', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('在购买日以即期汇率折算入账的固定资产，在资产负债表日无需根据汇率变动调整汇兑损益。（　　）', 'judge', '[]', '正确', '对于以历史成本计量的外币非货币性项目，已在交易发生日按当日即期汇率折算，资产负债表日不应改变其原记账本位币金额，不产生汇兑差额。', (SELECT id FROM knowledge_points WHERE title='外币折算'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('行政单位收到无偿调入的资产，应按该资产的市场价格和相关税费进行核算。（　　）', 'judge', '[]', '错误', '无偿调入的资产，其成本按照调出方账面价值加上相关税费等确定。', (SELECT id FROM knowledge_points WHERE title='政府与民间非营利组织会计'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('承租人转让原租赁的使用权资产后，在当期的资产负债表日应终止对于原租赁产生的租赁负债。（　　）', 'judge', '[]', '错误', '承租人转让原租赁的使用权资产后，在当期的资产负债表日应保留原租赁产生的租赁负债。', (SELECT id FROM knowledge_points WHERE title='租赁'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('对于核发电设备处置时产生的预计负债，应按照未来支付的金额减去处置利得之后的现值进行核算。（　　）', 'judge', '[]', '错误', '对于核发电设备处置时产生的预计负债，应按照未来支付金额的现值核算。核发电设备的处置利得不属于弃置费用，应当在发生时作为固定资产处置损益处理。', (SELECT id FROM knowledge_points WHERE title='或有事项'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023);
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('企业将一项对外出租并采用公允价值模式计量的房屋转为自用，转换日公允价值与原账面金额之间的差额计入（　　）。', 'single', '["A. 投资收益", "B. 其他收益", "C. 其他业务成本", "D. 公允价值变动损益"]', 'D', '公允价值模式计量的投资性房地产转为非投资性房地产，转换日公允价值与原账面余额之间的差额计入公允价值变动损益。', (SELECT id FROM knowledge_points WHERE title='投资性房地产'), 'medium', '["真题", "概念题"]', '考生回忆版-2024', 2024),
('企业购入以外币计价的债券，作为以公允价值计量且其变动计入当期损益的金融资产核算，在资产负债表日，外币折算的记账本位币与原记账本位币之间的差额，计入（　　）。', 'single', '["A. 其他综合收益", "B. 公允价值变动损益", "C. 资本公积", "D. 财务费用"]', 'B', '以公允价值计量且其变动计入当期损益的金融资产，期末应将外币折算后的记账本位币金额与原记账本位币金额之间的差额计入当期损益（公允价值变动损益）。', (SELECT id FROM knowledge_points WHERE title='金融资产'), 'medium', '["真题", "概念题"]', '考生回忆版-2024', 2024),
('下列选项中，属于以非货币性资产交换准则核算的是（　　）。', 'single', '["A. 以公允价值计量的价值为500万元的空调作为福利发放给职工", "B. 以公允价值计量的价值为300万元的生产设备与价值为300万元的使用权资产交换", "C. 以公允价值计量的价值为2000万元的不动产偿还2000万元的借款", "D. 以公允价值计量的价值为40万元管理用汽车与价值为60万元货车交换，并支付20万元差价"]', 'B', '选项A，属于向职工发放非货币性福利，适用职工薪酬准则；选项C，属于偿还借款，适用债务重组准则；选项D，支付补价比例＝20÷（40＋20）×100%＝33.33%＞25%，不属于非货币性资产交换。', (SELECT id FROM knowledge_points WHERE title='非货币性资产交换'), 'medium', '["真题", "概念题"]', '考生回忆版-2024', 2024),
('下列关于政府会计的表述中，正确的是（　　）。', 'single', '["A. 预算会计包括预算收入、预算支出和预算结余", "B. 政府预算会计以权责发生制为基础编制决算报告", "C. 政府财务会计以收付实现制为基础编制财务报告", "D. 事业单位对纳入部门预算管理的现金支付，不进行财务核算"]', 'A', '选项B，政府预算会计以收付实现制为基础编制决算报告；选项C，政府财务会计以权责发生制为基础编制财务报告；选项D，政府单位对于纳入部门预算管理的现金收支业务，在采用财务会计核算的同时应当进行预算会计核算。', (SELECT id FROM knowledge_points WHERE title='政府与民间非营利组织会计'), 'easy', '["真题", "概念题"]', '考生回忆版-2024', 2024),
('2×23年财务报告批准报出日为2×24年4月20日，下列发生的对财务情况有重大影响的事项中，应作为2×23年资产负债表日后调整事项的是（　　）。', 'single', '["A. 1月20日，公司发行债券", "B. 2月20日，火灾造成存货严重损失", "C. 3月10日，政府减税政策", "D. 4月10日，上年度已全部计入收入的商品因质量问题部分退回"]', 'D', '上年度已全部计入收入的商品在日后期间因质量问题退回，属于资产负债表日已存在状况的进一步证据，应作为调整事项；A、B、C属于非调整事项。', (SELECT id FROM knowledge_points WHERE title='资产负债表日后事项'), 'medium', '["真题", "概念题"]', '考生回忆版-2024', 2024),
('2×22年1月1日，甲公司以200万元的价格向乙公司销售其自产的货物，双方约定于2×24年，甲公司以220万元的价格购回。甲公司将其作为融资业务未确认收入，其体现的会计信息质量要求为（　　）。', 'single', '["A. 重要性", "B. 可比性", "C. 及时性", "D. 实质重于形式"]', 'D', '由于回购价格220万元大于出售价格200万元，该交易实质上具有融资性质，不应确认收入，体现了实质重于形式要求。', (SELECT id FROM knowledge_points WHERE title='会计信息质量要求'), 'easy', '["真题", "概念题"]', '考生回忆版-2024', 2024),
('甲公司2×23年度财务报告于2×24年4月20日经董事会批准对外公布。2×24年3月31日，甲公司发现其自行研发的软件2×23年7月1日已达到预定用途，其中研发支出应予以费用化的600万元计入了软件成本。该软件预计使用期限为5年，采用直线法进行摊销，预计净残值为零。甲公司按照净利润的10%计提法定盈余公积，不考虑所得税等因素的影响。上述事项对甲公司2×24年度未分配利润项目年初数的影响为（　　）万元。', 'single', '["A. -486", "B. -480", "C. -600", "D. -432"]', 'A', '上述事项对2×24年度未分配利润项目年初数的影响＝（－600＋600÷5×6/12）×（1－10%）＝－486（万元）。', (SELECT id FROM knowledge_points WHERE title='前期差错更正'), 'hard', '["真题", "计算题"]', '考生回忆版-2024', 2024);
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('经股东会批准，甲公司向其200名高级管理人员每人授予1万份股票期权，这些职员从授予日起在该公司连续服务3年，即可以每股5元的价格购买甲公司股票，授权日该股票期权的公允价值为每份10元。等待期有20人离职，180人行权，甲公司向行权人员发行自身股票，每股面值1元，发行180万股，共收到银行存款900万元。关于行权日的账务处理，以下说法正确的有（　　）。', 'multiple', '["A. 资本公积——其他资本公积减少1800万元", "B. 应付职工薪酬减少1500万元", "C. 资本公积——股本溢价增加2520万元", "D. 股本增加180万元"]', 'ACD', '行权期满时资本公积——其他资本公积减少额＝（200－20）×1×10＝1800（万元），选项A正确；本题属于权益结算的股份支付，不涉及应付职工薪酬核算，选项B错误；股本增加180万元，资本公积——股本溢价增加额＝1800＋900－180＝2520（万元），选项C、D正确。', (SELECT id FROM knowledge_points WHERE title='股份支付'), 'hard', '["真题", "计算题"]', '考生回忆版-2024', 2024),
('2×23年12月31日，甲公司与乙公司签订了一份租赁合同，将一台塑钢机出租给乙公司。甲公司将该租赁分类为融资租赁。下列各项中，属于甲公司租赁收款额的有（　　）。', 'multiple', '["A. 乙公司的母公司提供的担保余值", "B. 乙公司按年支付的固定租金", "C. 塑钢机的未担保余值", "D. 乙公司支付的租赁保证金"]', 'AB', '租赁收款额包括承租人需支付的固定付款额及实质固定付款额、取决于指数或比率的可变租赁付款额、购买选择权行权价格、终止租赁选择权需支付的款项以及由承租人、与承租人有关的一方以及有经济能力履行担保义务的独立第三方向出租人提供的担保余值。选项C通过"应收融资租赁款——未担保余值"科目核算，选项D通过"其他应付款"核算，均不属于租赁收款额。', (SELECT id FROM knowledge_points WHERE title='租赁'), 'medium', '["真题", "概念题"]', '考生回忆版-2024', 2024),
('下列各项中，企业应按政府补助准则进行会计处理的有（　　）。', 'multiple', '["A. 收到增值税出口退税", "B. 收到政府拨付的研究成果归政府享有的技术改造资金", "C. 收到政府拨付的就业创业补助", "D. 收到财政贴息资金"]', 'CD', '增值税出口退税实际上是政府退回企业事先垫付的进项税，不属于政府补助；研究成果归政府享有的资金不属于无偿取得，不属于政府补助；就业创业补助和财政贴息属于政府补助。', (SELECT id FROM knowledge_points WHERE title='政府补助'), 'medium', '["真题", "概念题"]', '考生回忆版-2024', 2024),
('2×22年5月1日，甲公司以800万元的价格购入一项专有技术用于生产M产品，预计使用该专有技术生产M产品1000万吨，按照产量法对该专有技术进行摊销。2×22年，甲公司共生产M产品60万吨，截至2×22年12月31日，M产品尚未对外出售。2×23年1月1日，甲公司改变经营战略，将M产品的未来产量调整为800万吨，2×23年末，甲公司生产M产品100万吨。2×23年12月31日，进行减值测试，该专有技术的可收回金额为600万元，不考虑其他因素，下列各项关于专有技术会计处理的表述中正确的有（　　）。', 'multiple', '["A. 2×22年末因该专有技术摊销而减少的2×22年末营业利润48万元", "B. 2×23年末与该专有技术相关资产减值损失58万元", "C. 2×23年12月31日该专有技术在资产负债表中的列报金额为600万元", "D. 2×23年该专有技术的摊销金额为100万元"]', 'BC', '2×22年专有技术摊销计入制造费用，金额＝60÷1000×800＝48（万元），M产品尚未对外出售，对营业利润无影响，选项A错误；2×23年发生会计估计变更，专有技术新的原值＝800－48＝752（万元），当年摊销金额＝752÷800×100＝94（万元），选项D错误；2×23年末计提减值前账面价值＝752－94＝658（万元），可收回金额600万元，计提减值58万元，选项B正确；列报金额为账面价值600万元，选项C正确。', (SELECT id FROM knowledge_points WHERE title='无形资产'), 'hard', '["真题", "计算题"]', '考生回忆版-2024', 2024),
('下列各项中，应计入企业自行建造固定资产初始入账成本的有（　　）。', 'multiple', '["A. 建造过程中发生的负荷联合试车费", "B. 分摊的为建造工程发生的可行性研究费", "C. 建造过程中发生的工程物资盘亏净损失", "D. 建造过程中发生建设施工人员的防暑降温费"]', 'ABCD', '自行建造出包方式下的固定资产入账价值＝建筑工程支出＋安装工程支出＋安装设备支出＋分摊的待摊支出。待摊支出包括管理费、可行性研究费用、符合资本化条件的借款费用、建设期间发生的工程物资盘亏报废及毁损净损失、负荷联合试车费等，选项ABCD均计入固定资产初始入账成本。', (SELECT id FROM knowledge_points WHERE title='固定资产'), 'medium', '["真题", "概念题"]', '考生回忆版-2024', 2024),
('下列关于指定为以公允价值计量且其变动计入其他综合收益的非交易性权益工具投资的会计处理表述中，正确的有（　　）。', 'multiple', '["A. 取得投资时发生的交易费用计入投资收益", "B. 持有期间的公允价值变动计入其他综合收益", "C. 终止确认时将持有期间的公允价值变动转入留存收益", "D. 持有期间宣告发放的现金股利计入其他综合收益"]', 'BC', '指定为以公允价值计量且其变动计入其他综合收益的非交易性权益工具投资，取得时交易费用计入初始成本，选项A错误；持有期间公允价值变动计入其他综合收益，选项B正确；终止确认时累计公允价值变动转入留存收益，选项C正确；持有期间宣告发放的现金股利计入投资收益，选项D错误。', (SELECT id FROM knowledge_points WHERE title='金融资产'), 'medium', '["真题", "概念题"]', '考生回忆版-2024', 2024);
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('企业生产经营期间正常出售固定资产产生的净损失应计入营业外支出。（　　）', 'judge', '[]', '错误', '固定资产正常出售的净损益计入资产处置损益，报废净损失计入营业外支出。', (SELECT id FROM knowledge_points WHERE title='固定资产'), 'easy', '["真题", "判断题"]', '考生回忆版-2024', 2024),
('对于使用寿命不确定的无形资产，在不存在减值迹象时，企业无需进行减值测试。（　　）', 'judge', '[]', '错误', '对使用寿命不确定的无形资产，无论是否存在减值迹象，至少应当每年进行减值测试。', (SELECT id FROM knowledge_points WHERE title='无形资产'), 'easy', '["真题", "判断题"]', '考生回忆版-2024', 2024),
('与收益相关的政府补助如果用于补偿企业以后期间的相关成本或损失，企业采用净额法核算的，应于收到时计入当期损益。（　　）', 'judge', '[]', '错误', '与收益相关的政府补助用于补偿企业以后期间发生的相关成本费用或损失的，净额法下企业应当将其确认为递延收益，并在确认相关费用或损失的期间冲减相关成本费用。', (SELECT id FROM knowledge_points WHERE title='政府补助'), 'medium', '["真题", "判断题"]', '考生回忆版-2024', 2024),
('公司以上市子公司的股票授予本公司高管作为股权激励的，母公司在个别财务报表中应按以权益结算的股份支付进行会计处理。（　　）', 'judge', '[]', '错误', '结算企业不是以其本身权益工具而是以集团内其他企业的权益工具结算的，应当将该股份支付交易作为现金结算的股份支付进行会计处理。', (SELECT id FROM knowledge_points WHERE title='股份支付'), 'medium', '["真题", "判断题"]', '考生回忆版-2024', 2024),
('在以公允价值为基础计量的非货币性资产交换中，如果有确凿证据表明换入资产的公允价值更加可靠的，企业应在终止确认换出资产时，将换入资产的公允价值与换出资产账面价值之间的差额计入当期损益。（　　）', 'judge', '[]', '正确', '以公允价值为基础计量的非货币性资产交换，有确凿证据表明换入资产公允价值更可靠的，按换入资产公允价值计量换出资产，换入资产公允价值与换出资产账面价值的差额计入当期损益。', (SELECT id FROM knowledge_points WHERE title='非货币性资产交换'), 'medium', '["真题", "判断题"]', '考生回忆版-2024', 2024),
('企业重新计量设定受益计划净负债或净资产所产生的变动应计入其他综合收益，在后续会计期间不允许转回至损益。（　　）', 'judge', '[]', '正确', '企业应当将重新计量设定受益计划净负债或净资产所产生的变动计入其他综合收益，并且在后续会计期间不允许转回至损益。', (SELECT id FROM knowledge_points WHERE title='职工薪酬'), 'medium', '["真题", "判断题"]', '考生回忆版-2024', 2024),
('民间非营利组织的董事会、理事会或类似权力机构对净资产的使用作出限定性决策的，该净资产不应作为限定性净资产。（　　）', 'judge', '[]', '正确', '民间非营利组织董事会、理事会或类似权力机构对净资产的使用所作的限定性决策、决议或拨款限额等，属于内部管理上对资产使用所作的限制，不属于所界定的限定性净资产。', (SELECT id FROM knowledge_points WHERE title='政府与民间非营利组织会计'), 'medium', '["真题", "判断题"]', '考生回忆版-2024', 2024),
('承租人能够合理确定租赁期届满时取得租赁资产所有权的，应在租赁资产剩余使用寿命内计提折旧。（　　）', 'judge', '[]', '正确', '承租人能够合理确定租赁期届满时取得租赁资产所有权的，应当在租赁资产剩余使用寿命内计提折旧；无法合理确定的，应当在租赁期与租赁资产剩余使用寿命两者孰短的期间内计提折旧。', (SELECT id FROM knowledge_points WHERE title='租赁'), 'easy', '["真题", "判断题"]', '考生回忆版-2024', 2024),
('因出售部分股权丧失控制权，企业将按成本法核算的长期股权投资改按权益法核算的，属于会计政策变更。（　　）', 'judge', '[]', '错误', '因持股比例改变导致的成本法转为权益法核算，是现行准则下的正常转换，不属于会计政策变更。', (SELECT id FROM knowledge_points WHERE title='长期股权投资'), 'medium', '["真题", "判断题"]', '考生回忆版-2024', 2024),
('企业收回的委托外单位加工的产品直接用于对外销售的，受托方代收代缴的消费税应计入产品成本。（　　）', 'judge', '[]', '正确', '委托加工物资收回后用于直接出售的，受托方代收代缴的消费税计入存货成本；用于连续生产应税消费品的，不计入存货成本，应记入"应交税费——应交消费税"科目借方。', (SELECT id FROM knowledge_points WHERE title='存货的初始计量'), 'medium', '["真题", "判断题"]', '考生回忆版-2024', 2024);
INSERT INTO knowledge_points ("title", "content", "chapterNumber", "sortOrder", "importance", "tags") VALUES
('借款费用', '借款费用包括借款利息、折价或溢价的摊销、辅助费用以及因外币借款而发生的汇兑差额等。资本化期间的确定与资本化金额的计算是核心考点。', '7.1', 30, 'important', '["借款费用", "重点"]'),
('公允价值计量', '公允价值是市场参与者在计量日发生的有序交易中，出售一项资产所能收到或转移一项负债所需支付的价格。公允价值层次分为第一、二、三层次。', '1.3', 31, 'important', '["公允价值", "重点"]'),
('存货的期末计量', '资产负债表日，存货应当按照成本与可变现净值孰低计量。可变现净值的确定与存货跌价准备的计提、转回是核心考点。', '2.2', 32, 'important', '["存货", "减值"]'),
('资产减值', '资产存在减值迹象的，应当估计其可收回金额，按可收回金额低于账面价值的差额计提减值准备。商誉和使用寿命不确定的无形资产无论是否存在减值迹象，至少每年进行减值测试。', '8.1', 33, 'important', '["资产减值", "重点"]');
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('甲公司以人民币作为记账本位币，乙公司是甲公司的境外子公司，以美元作为记账本位币。甲公司将境外子公司财务报表折算为人民币时，以资产负债表日即期汇率折算的财务报表项目是（　　）。', 'single', '["A. 股本", "B. 应付债券", "C. 盈余公积", "D. 财务费用"]', 'B', '资产负债表中的资产和负债项目，应采用资产负债表日即期汇率折算；所有者权益项目除"未分配利润"项目外，其他项目采用发生时的即期汇率折算；利润表中的收入和费用项目，采用交易发生日的即期汇率折算。选项A、C属于所有者权益项目，选项D属于利润表费用项目，均不采用资产负债表日的即期汇率折算。', (SELECT id FROM knowledge_points WHERE title='外币折算'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('房地产开发企业将作为存货的房屋转换为采用公允价值模式计量的投资性房地产时，应将转换日该房屋的公允价值大于账面价值的差额计入（　　）。', 'single', '["A. 公允价值变动损益", "B. 投资收益", "C. 其他综合收益", "D. 资本公积"]', 'C', '自用房地产或存货转换为采用公允价值模式计量的投资性房地产时，转换当日的公允价值小于原账面价值的，差额计入当期损益（公允价值变动损益）；公允价值大于原账面价值的，差额计入其他综合收益。', (SELECT id FROM knowledge_points WHERE title='投资性房地产'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('增值税一般纳税人公司以自产产品作为福利，发放给公司管理员工，适用的增值税税率为13%，共发放了5000件，每件售价为0.6万元，每件成本为0.4万元。不考虑其他因素，该事项对当年利润的影响金额为（　　）万元。', 'single', '["A. -2000", "B. 1000", "C. -2390", "D. 3000"]', 'C', '该事项对当年利润的影响金额＝主营业务收入3000－管理费用3390－主营业务成本2000＝－2390（万元）。管理费用＝5000×0.6×1.13＝3390（万元），主营业务收入＝5000×0.6＝3000（万元），主营业务成本＝5000×0.4＝2000（万元）。', (SELECT id FROM knowledge_points WHERE title='职工薪酬'), 'hard', '["真题", "计算题"]', '考生回忆版-2023', 2023),
('甲公司取得乙公司60%股份，可以对其实施控制，甲公司当年收到乙公司发放的现金股利48万元，甲公司个别现金流量表中"取得投资收益收到的现金"项目为300万元，乙公司个别现金流量表中"取得投资收益收到的现金"项目为90万元。不考虑其他因素，当年甲公司合并现金流量表中"取得投资收益收到的现金"项目列示的金额为（　　）万元。', 'single', '["A. 342", "B. 354", "C. 306", "D. 356"]', 'A', '编制合并现金流量表时，母公司与子公司相互之间产生的现金流量应当抵销。甲公司因乙公司发放现金股利收到现金48万元应该抵销，所以合并现金流量表中"取得投资收益收到的现金"项目列示的金额＝300＋90－48＝342（万元）。', (SELECT id FROM knowledge_points WHERE title='合并财务报表'), 'hard', '["真题", "计算题"]', '考生回忆版-2023', 2023);
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('按照我国《会计人员职业道德规范》，新时代会计人员应当遵守的职业道德有（　　）。', 'multiple', '["A. 坚持诚信，守法奉公", "B. 坚持准则，守责敬业", "C. 坚持惯例，守护传统", "D. 坚持学习，守正创新"]', 'ABD', '《会计人员职业道德规范》将新时代会计人员职业道德要求总结提炼为三条核心表述，即"坚持诚信，守法奉公""坚持准则，守责敬业""坚持学习，守正创新"。', (SELECT id FROM knowledge_points WHERE title='会计概念'), 'easy', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('下列各项中，企业应按政府补助准则进行会计处理的有（　　）。', 'multiple', '["A. 收到政府无偿给予的价值120万元的环保设备", "B. 收到增值税出口退税800万元", "C. 收到政府无偿拨款500万元", "D. 收到政府贴息200万元"]', 'ACD', '政府补助主要形式包括政府对企业的无偿拨款、税收返还、财政贴息，以及无偿给予非货币性资产等。选项B，增值税出口退税实际上是政府退回企业事先垫付的进项税，不属于政府补助。', (SELECT id FROM knowledge_points WHERE title='政府补助'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('企业2×22年财务报表经批准于2×23年3月31日报出，下列各项重大交易或者事项中，属于资产负债表日后调整事项的有（　　）。', 'multiple', '["A. 2×23年2月10日外汇汇率发生重大变化", "B. 2×23年2月20日发现上年度重大会计差错", "C. 2×23年3月1日资本公积转增资本", "D. 2×23年1月5日上一年销售的产品被全部退回"]', 'BD', '发现上年度重大会计差错属于资产负债表日后调整事项；上一年销售的产品被全部退回，属于资产负债表日已存在状况的进一步证据，属于调整事项。选项A、C属于非调整事项。', (SELECT id FROM knowledge_points WHERE title='资产负债表日后事项'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('下列各项关于企业职工薪酬会计处理的表述中，正确的有（　　）。', 'multiple', '["A. 企业实施职工内部退休计划的，在职工正式退休之前，比照辞退福利处理", "B. 企业计提的工会经费，应按职工提供服务的受益对象计入当期损益或相关资产成本", "C. 与未行使的短期累积带薪缺勤权利相关的职工薪酬，应以累积未行使权利而增加的预期支付金额计量", "D. 与短期非累积带薪缺勤相关的职工薪酬应在职工实际发生缺勤的会计期间确认"]', 'ABCD', '选项A，实施职工内部退休计划的，在职工正式退休之前，比照辞退福利处理；选项B，工会经费应按职工提供服务的受益对象计入当期损益或相关资产成本；选项C，累积带薪缺勤应以累积未行使权利而增加的预期支付金额计量；选项D，短期非累积带薪缺勤应在职工实际发生缺勤的会计期间确认。', (SELECT id FROM knowledge_points WHERE title='职工薪酬'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023);
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('企业以公允价值计量相关负债，应当最先以活跃市场上相同负债未经调整的报价计量。（　　）', 'judge', '[]', '正确', '企业以公允价值计量负债，应当优先使用相关的可观察输入值。第一层次输入值是在计量日能够取得的相同资产或负债在活跃市场上未经调整的报价。', (SELECT id FROM knowledge_points WHERE title='公允价值计量'), 'easy', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('企业持有待售的无形资产的处置损益在利润表中应当以终止经营损益列报。（　　）', 'judge', '[]', '错误', '终止经营是指能够单独区分的组成部分，且该组成部分已经处置或划分为持有待售类别，代表一项独立的主要业务或一个单独的主要经营地区。单独持有待售的无形资产不属于终止经营，其处置损益不按终止经营损益列报。', (SELECT id FROM knowledge_points WHERE title='会计概念'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('不可撤销的亏损合同存在标的资产的，预计亏损超过标的资产的减值损失的，超过部分应确认预计负债。（　　）', 'judge', '[]', '正确', '亏损合同存在标的资产的，应当对标的资产进行减值测试并按规定确认减值损失，企业通常不需要确认预计负债；如果预计亏损超过该减值损失，应将超过部分确认为预计负债。', (SELECT id FROM knowledge_points WHERE title='或有事项'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('如本期存货可变现净值高于成本的影响因素不是以前减记存货价值的影响因素，则不允许转回计提的存货跌价准备。（　　）', 'judge', '[]', '正确', '导致存货跌价准备转回的是以前减记存货价值的影响因素的消失，而不是在当期造成存货可变现净值高于其成本的其他影响因素。如果本期导致存货可变现净值高于其成本的影响因素不是以前减记该存货价值的影响因素，则不允许将该存货跌价准备转回。', (SELECT id FROM knowledge_points WHERE title='存货的期末计量'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('母公司在编制合并资产负债表时，子公司持有的母公司的长期股权投资应视为企业集团的库存股。（　　）', 'judge', '[]', '正确', '合并财务报表准则规定，子公司持有母公司的长期股权投资，应当视为企业集团的库存股，作为所有者权益的减项，在合并资产负债表中所有者权益项目下以"减：库存股"项目列示。', (SELECT id FROM knowledge_points WHERE title='合并财务报表'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('如果在资产负债表日，没有迹象表明合并中形成的商誉存在减值迹象的，企业无须为商誉进行减值测试。（　　）', 'judge', '[]', '错误', '对于企业合并所形成的商誉，无论是否存在减值迹象，至少应当每年进行减值测试。', (SELECT id FROM knowledge_points WHERE title='资产减值'), 'easy', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('甲公司为建造一栋办公楼占用一笔外币一般借款，该笔借款在资本化期间的本金和利息所产生的汇兑差额应当资本化。（　　）', 'judge', '[]', '错误', '在资本化期间内，外币专门借款本金及其利息的汇兑差额应当予以资本化；除外币专门借款之外的其他外币借款本金及其利息所产生的汇兑差额，应当作为财务费用计入当期损益。外币一般借款的汇兑差额不资本化。', (SELECT id FROM knowledge_points WHERE title='借款费用'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('以公允价值计量且其变动计入其他综合收益的非交易性权益工具投资转为权益法核算的长期股权投资，已计入其他综合收益的公允价值变动转入投资收益。（　　）', 'judge', '[]', '错误', '指定为以公允价值计量且其变动计入其他综合收益的非交易性权益工具投资，已计入其他综合收益的公允价值变动在处置时应转入留存收益，而不是投资收益。', (SELECT id FROM knowledge_points WHERE title='金融资产'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('非同一控制下的控股合并，合并方合并成本高于合并中取得的被合并方可辨认净资产公允价值份额的差额，应在合并方个别报表中以商誉列示。（　　）', 'judge', '[]', '错误', '非同一控制下的控股合并，收购方合并成本高于合并中取得的被收购方可辨认净资产公允价值份额的差额，应在合并财务报表中以商誉列示，不是在个别财务报表中列示。', (SELECT id FROM knowledge_points WHERE title='合并财务报表'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('比较财务报表可比期间以前的会计政策变更累积影响数应调整比较财务报表最早期间的期初留存收益。（　　）', 'judge', '[]', '正确', '对于比较财务报表可比期间以前的会计政策变更的累积影响数，应调整比较财务报表最早期间的期初留存收益，财务报表其他相关项目的数字也应一并调整。', (SELECT id FROM knowledge_points WHERE title='会计政策变更'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023);
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('下列各项中，企业应当计入管理费用的是（　　）。', 'single', '["A. 按利润分享计划给予生产部门管理人员的额外薪酬", "B. 为生产部门管理人员计提和缴存的医疗保险费", "C. 与生产部门管理人员解除劳动关系支付的一次性款项补偿金额", "D. 供生产部门管理人员无偿使用的小汽车的租金支出"]', 'C', '选项A、B、D，均计入制造费用；选项C，属于辞退福利，不按受益对象区分，计入管理费用。', (SELECT id FROM knowledge_points WHERE title='职工薪酬'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('甲公司适用的所得税税率为25%，预计未来期间能够产生足够的应纳税所得额用以抵减可抵扣暂时性差异。2022年甲公司实现的利润总额为1000万元，其中国债利息收入50万元，违法罚款支出60万元，当年新增一台其初始入账成本与计税基础均为600万元的行政管理设备，当期已提折旧60万元，税法规定允许抵扣40万元。假定税法规定国债利息收入免税，违法罚款支出不允许税前抵扣。假定不考虑其他因素，甲公司2022年所得税费用的金额为（　　）万元。', 'single', '["A. 247.5", "B. 252.5", "C. 257.5", "D. 250"]', 'B', '甲公司2022年所得税费用的金额＝（1000－50＋60）×25%＝252.5（万元）。', (SELECT id FROM knowledge_points WHERE title='所得税'), 'hard', '["真题", "计算题"]', '考生回忆版-2023', 2023),
('甲公司和乙公司均为丙公司创立的子公司，2022年1月5日甲公司以银行存款800万元和一项账面价值为1200万元、公允价值为1500万元的固定资产作为合并对价，获得乙公司80%的有表决权股份。该合并为同一控制下的企业合并，甲公司能够对乙公司实施控制。2022年1月5日，乙公司可辨认净资产的公允价值为4600万元，其所有者权益在最终控制方丙公司的合并财务报表中的账面价值为4500万元。不考虑其他因素，甲公司2022年1月5日购入该长期股权投资的初始投资成本为（　　）万元。', 'single', '["A. 2000", "B. 2300", "C. 3680", "D. 3600"]', 'D', '同一控制下企业合并形成的长期股权投资，初始投资成本＝被合并方所有者权益在最终控制方合并财务报表中的账面价值份额＝4500×80%＝3600（万元）。', (SELECT id FROM knowledge_points WHERE title='长期股权投资'), 'medium', '["真题", "计算题"]', '考生回忆版-2023', 2023),
('2022年1月10日，甲公司因建造工程向银行申请一笔专门借款。2022年2月1日，甲公司投入一批钢材到建造工程。2022年4月10日，甲公司申请的专门借款银行审批通过，并于当日收到款项。2023年3月1日建造工程完工，厂房达到预定可使用状态。2023年4月1日，办理竣工决算并正式投入使用。该专门借款利息费用应当予以资本化的期间为（　　）。', 'single', '["A. 2022年2月1日～2023年4月1日", "B. 2022年2月1日～2023年3月1日", "C. 2022年4月10日～2023年3月1日", "D. 2022年4月10日～2023年4月1日"]', 'C', '借款费用开始资本化必须同时满足三个条件：资产支出已经发生、借款费用已经发生、为使资产达到预定可使用或可销售状态所必要的购建或生产活动已经开始，所以2022年4月10日为开始资本化时点；2023年3月1日达到预定可使用状态，为停止资本化时点。', (SELECT id FROM knowledge_points WHERE title='借款费用'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('甲公司适用的所得税税率为25%，2022年度所得税汇算清缴于2023年5月15日完成。2021年12月31日，甲公司与承租方乙公司签订写字楼租赁合同。租赁期限为2022年1月1日～2023年12月31日，月租金10万元，并于每月末支付。2023年4月10日，甲公司发现2022年度租金收入漏计，甲公司将该重要差错采用追溯重述法进行差错更正。该差错更正对2023年初留存收益产生的影响为（　　）万元。', 'single', '["A. 90", "B. 120", "C. -90", "D. -120"]', 'A', '该差错更正对2023年初留存收益产生的影响＝10×12×（1－25%）＝90（万元）。', (SELECT id FROM knowledge_points WHERE title='前期差错更正'), 'medium', '["真题", "计算题"]', '考生回忆版-2023', 2023),
('2021年12月31日，甲建筑公司与乙公司签订一项建造工程合同，合同约定建造期限为2022年1月1日～2023年12月31日。2022年6月30日，甲公司确认的与建造合同相关的营业收入为12000万元，与乙公司结算的合同价款为11000万元。2022年12月31日，甲公司确认的与该建造合同相关的营业收入为11000万元，与乙公司结算的合同价款为11800万元。假定不考虑其他因素，2022年甲公司与该建造合同相关的合同资产项目金额为（　　）万元。', 'single', '["A. 200", "B. 800", "C. 1000", "D. 1800"]', 'A', '2022年甲公司与该建造合同相关的合同资产项目金额＝（12000－11000）＋（11000－11800）＝200（万元）。"合同结算"科目余额在借方的，在资产负债表中作为"合同资产"项目列示。', (SELECT id FROM knowledge_points WHERE title='收入确认'), 'medium', '["真题", "计算题"]', '考生回忆版-2023', 2023);
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('甲公司2×22年度财务报告的批准报出日为2×23年4月21日。不考虑其他因素，下列各项甲公司2×23年发生的对财务状况有重大影响的交易或事项中，应作为2×22年度资产负债表日后非调整事项的有（　　）。', 'multiple', '["A. 2×23年2月20日，发生安全生产事故造成重大财产损失", "B. 2×23年3月15日，以资本公积转增资本", "C. 2×23年2月11日，收到客户退回2×22年11月销售的部分商品", "D. 2×23年3月18日，股东大会通过2×22年的利润分配方案"]', 'AB', '选项A、B，属于非调整事项；选项C，属于资产负债表日后调整事项；选项D，利润分配方案中提取法定盈余公积属于调整事项，分配股利属于非调整事项，但本题中答案以正保会计网校参考答案为准，为AB。', (SELECT id FROM knowledge_points WHERE title='资产负债表日后事项'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('下列各项关于合同履约成本的相关表述中，正确的有（　　）。', 'multiple', '["A. 与一份当前或预期取得的合同直接相关", "B. 初始确认时摊销期限不超过一年或一个营业周期", "C. 已计提减值准备的以后期间不得转回", "D. 应采用与该合同履约成本相关的收入确认相同的基础进行摊销并计入当期损益"]', 'AD', '选项B，合同履约成本初始确认时摊销期限有可能超过一年或一个正常营业周期；选项C，已计提减值准备的以后期间可以转回。', (SELECT id FROM knowledge_points WHERE title='收入确认'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('甲公司因排放污水污染环境被当地居民起诉至法院，当地居民要求赔偿损失200万元，甲公司经调查发现污水排放不达标系所购乙公司污水处理设备存在质量问题所致。经协商，乙公司同意补偿甲公司的诉讼赔偿款。截至2×22年12月31日，法院尚未对该诉讼作出判决，甲公司预计其很可能败诉，将要支付的赔偿金额为110万元至130万元的某一金额，且该区间内的金额可能性都相同，同时基本确定能够从乙公司收到的诉讼补偿为100万元。不考虑其他因素，下列各项关于甲公司对该未决诉讼的会计处理的表述中，正确的有（　　）。', 'multiple', '["A. 确认营业外支出100万元", "B. 确认预计负债120万元", "C. 利润总额减少20万元", "D. 确认一项资产100万元"]', 'BCD', '甲公司确认预计负债＝（110＋130）÷2＝120（万元）；预计收到的补偿金额，只能在基本确定能够收到时作为资产单独确认，且确认的补偿金额不应超过所确认负债的账面价值，应确认其他应收款100万元。应确认营业外支出20万元（120－100），利润总额减少20万元。', (SELECT id FROM knowledge_points WHERE title='或有事项'), 'hard', '["真题", "计算题"]', '考生回忆版-2023', 2023),
('甲公司为生产环保材料的高新企业，下列各项中，甲公司应按照政府补助准则进行会计处理的有（　　）。', 'multiple', '["A. 收到科技创新政府奖励800万元", "B. 收到增值税出口退税额1000万元", "C. 因符合研发费用加计扣除政策，增加计税抵扣额1000万元", "D. 收到失业保险稳岗补贴600万元"]', 'AD', '政府补助的主要形式包括政府对企业的无偿拨款、税收返还、财政贴息，以及无偿给予非货币性资产等。选项B，增值税出口退税实际上是政府退回企业事先垫付的进项税，不属于政府补助；选项C，增加计税抵扣额，不涉及资产的直接转移，不适用政府补助准则。', (SELECT id FROM knowledge_points WHERE title='政府补助'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023),
('下列关于租赁的各交易事项中，需要采用使用权资产和租赁负债核算的有（　　）。', 'multiple', '["A. 租赁期为8个月，租赁设备到期，承租人有优先购买权的不可撤销合同", "B. 租赁期为6个月，租赁到期，承租人直接购买资产所有权的不可撤销合同", "C. 5个合同资产和3个低价值资产，低价值融入设备安装器", "D. 低价值资产租赁"]', 'A', '对于短期租赁和低价值资产租赁，承租人可以选择不确认使用权资产和租赁负债。选项A，包含购买选择权的租赁不属于短期租赁，需要采用使用权资产和租赁负债核算；选项B，租赁期不超过12个月，属于短期租赁，可选择不确认。选项C、D属于低价值资产租赁，可选择不确认。（注：本题为2023年考生回忆版，选项C原文OCR可能存在误差，答案以正保会计网校参考答案为准）', (SELECT id FROM knowledge_points WHERE title='租赁'), 'medium', '["真题", "概念题"]', '考生回忆版-2023', 2023);
INSERT INTO questions ("content", "type", "options", "correctAnswer", "explanation", "knowledgePointId", "difficulty", "tags", "source", "year") VALUES
('企业以公允价值计量资产时，不考虑针对资产持有者所设置的限制。（　　）', 'judge', '[]', '正确', '企业以公允价值计量相关资产，应当考虑出售或使用该资产所存在的限制因素，但应区分该限制是针对资产持有者的，还是针对该资产本身的。如果该限制是针对相关资产本身的，应当考虑该限制；如果该限制是针对资产持有者的，则不应考虑该限制因素。', (SELECT id FROM knowledge_points WHERE title='公允价值计量'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('企业收到用于补偿其已发生损失的与收益相关的政府补助，将其直接计入当期损益或冲减相关成本费用。（　　）', 'judge', '[]', '正确', '与收益相关的政府补助如果用于补偿企业已发生的相关成本费用或损失，企业应当将其直接计入当期损益（总额法）或冲减相关成本费用（净额法）。', (SELECT id FROM knowledge_points WHERE title='政府补助'), 'easy', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('售后租回交易中的资产转让属于销售的，承租人应按照租赁期开始日尚未支付的租赁付款额的现值加上承租人发生的初始直接费用计量使用权资产。（　　）', 'judge', '[]', '错误', '售后租回交易中的资产转让属于销售的，卖方兼承租人应当按原资产账面价值中与租回获得的使用权有关的部分，计量售后租回所形成的使用权资产，并仅就转让至买方兼出租人的权利确认相关利得或损失。', (SELECT id FROM knowledge_points WHERE title='租赁'), 'hard', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('符合《中小企业划型标准规定》的且具有金融性质的小企业适用《小企业会计准则》。（　　）', 'judge', '[]', '错误', '小企业会计准则主要适用于符合《中小企业划型标准规定》所规定的小型企业标准的企业，但以下三类小企业除外：股票或债券在市场上公开交易的小企业；金融机构或其他具有金融性质的小企业；企业集体内的母公司和子公司。', (SELECT id FROM knowledge_points WHERE title='会计概念'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('企业对以公允价值计量且其变动计入当期损益的金融负债进行初始计量时，相关交易费用应直接计入当期损益。（　　）', 'judge', '[]', '正确', '对于以公允价值计量且其变动计入当期损益的金融负债，其初始计量时涉及的相关交易费用应当直接计入当期损益。', (SELECT id FROM knowledge_points WHERE title='金融资产'), 'easy', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('企业处置专为转售而取得的子公司相关损益应在利润表中作为持续经营损益列报。（　　）', 'judge', '[]', '错误', '处置专为转售而取得的子公司属于终止经营，终止经营的相关损益应当作为终止经营损益列报，而不是持续经营损益。', (SELECT id FROM knowledge_points WHERE title='会计概念'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('在以公允价值为基础计量的非货币性资产交换中，换出资产为投资性房地产的，企业应将换出资产公允价值与账面价值的差额计入投资收益。（　　）', 'judge', '[]', '错误', '以公允价值为基础计量的非货币性资产交换中，换出资产按出售处理，换出资产为投资性房地产的，应按换出资产公允价值或换入资产公允价值确认其他业务收入，按换出资产账面价值结转其他业务成本，差额计入其他业务收入/成本，不是投资收益。', (SELECT id FROM knowledge_points WHERE title='非货币性资产交换'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('企业计量递延所得税负债时，应以相关应纳税暂时性差异转回期间适用的企业所得税税率为基础计算确定。（　　）', 'judge', '[]', '正确', '递延所得税负债应以相关应纳税暂时性差异转回期间适用的所得税税率计量。', (SELECT id FROM knowledge_points WHERE title='所得税'), 'easy', '["真题", "判断题"]', '考生回忆版-2023', 2023),
('企业向客户授予知识产权许可，并约定按客户使用该知识产权实现的销售额收取特许权使用费的，企业应在客户后续销售实际发生与企业履行相关履约义务二者孰晚的时点确认收入。（　　）', 'judge', '[]', '正确', '企业向客户授予知识产权许可，并约定按客户实际销售或使用情况（如按照客户的销售额）收取特许权使用费的，应当在客户后续销售或使用行为实际发生与企业履行相关履约义务二者孰晚的时点确认收入。', (SELECT id FROM knowledge_points WHERE title='收入确认'), 'medium', '["真题", "判断题"]', '考生回忆版-2023', 2023);
